-- Preserve a tenant-local snapshot before updating standard blocks.
insert into settings(tenant_id,key,value)
select tenant_id,'template:rules:before-042',jsonb_build_object('bots',(select coalesce(jsonb_agg(jsonb_build_object('id',b.id,'graph',b.graph)),'[]') from bots b where b.tenant_id=t.id),'agents',(select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'prompt',a.prompt,'rules',a.rules,'forbidden',a.forbidden)),'[]') from agents a where a.tenant_id=t.id)) from tenants t cross join lateral (select t.id as tenant_id) scope
on conflict(tenant_id,key) do nothing;
alter table conversations add column human_accepted_at timestamptz;
alter table conversations add column handoff_since timestamptz;
alter table conversations add column handoff_state text;
alter table conversations add column fallback_started_at timestamptz;
alter table teams add column module_access jsonb not null default '{}';
create index continuity_waiting on conversations(tenant_id,handoff_state,handoff_since) where status='open';
alter table conversations add column ai_service_role text;
create function continuity_transition() returns trigger language plpgsql as $$ begin
 if new.status='closed' then new.handoff_state=null;new.handoff_since=null;new.human_accepted_at=null;new.fallback_started_at=null;
 elsif new.human_accepted_at is distinct from old.human_accepted_at and new.human_accepted_at is not null then new.handoff_state='accepted';
 elsif new.automation_mode='human' and (old.automation_mode is distinct from 'human' or old.team_id is distinct from new.team_id or old.assignee_id is distinct from new.assignee_id) then
 new.handoff_state=case when new.handoff_state='check_required' then 'check_required' when old.handoff_state in ('ai_active','human_final','offering','check_required') then 'human_final' else 'waiting' end;
 new.handoff_since=case when old.automation_mode='human' then coalesce(old.handoff_since,now()) else now() end;new.human_accepted_at=null;
 end if;if new.status='closed' or new.automation_mode in ('human','bot') then new.ai_service_role=null;end if;return new;end $$;
create trigger continuity_state before update on conversations for each row execute function continuity_transition();
-- Old templates may still carry the former phone restriction. Runtime ignores it too.
update bots b set graph=jsonb_set(b.graph,'{nodes}',(select jsonb_agg(case when n->>'type'='asaas' then jsonb_set(jsonb_set(n,'{data,verifyPhone}','false'::jsonb,true),'{data,text}',to_jsonb(case when n#>>'{data,text}' like '%telefone desta conversa deve corresponder%' then 'Informe o CPF ou CNPJ do cadastro que deseja consultar. Você pode consultar em nome do titular.' else coalesce(n#>>'{data,text}','Informe o CPF ou CNPJ do cadastro que deseja consultar.') end),true) else n end order by ord) from jsonb_array_elements(b.graph->'nodes') with ordinality as t(n,ord))) where jsonb_typeof(b.graph->'nodes')='array' and exists(select 1 from jsonb_array_elements(b.graph->'nodes') n where n->>'type'='asaas');
update agents set rules=replace(rules,'CPF/CNPJ isolado não autoriza mostrar débitos: o fluxo verifica o telefone cadastrado no Asaas; divergência segue para atendimento humano.','A consulta usa CPF/CNPJ válido, inclusive por representante. Não exigir coincidência de telefone; manter documento mascarado.') where rules like '%o fluxo verifica o telefone cadastrado no Asaas%';
-- Update only the standard commercial contact nodes, retaining custom flows and IDs.
update bots b set graph=jsonb_set(graph,'{nodes}',(select jsonb_agg(case when n->>'id' in ('comercial_pf','comercial_pj') and n->>'type'='message' and n#>>'{data,text}' like '%wa.me/%' then n||jsonb_build_object('type','transfer','data',jsonb_build_object('target','ai','role','seller','person_type',case when n->>'id'='comercial_pf' then 'pf' else 'pj' end,'fallback_team_id',(select (x#>>'{data,team_id}')::int from jsonb_array_elements(b.graph->'nodes') x where x->>'id'='comercial' and x->>'type'='transfer' limit 1),'fallback_phone',case when n->>'id'='comercial_pf' then '5566999776407' else '5566996968893' end)) else n end order by ord) from jsonb_array_elements(b.graph->'nodes') with ordinality t(n,ord))) where exists(select 1 from jsonb_array_elements(coalesce(b.graph->'nodes','[]')) x where x->>'id'='comercial_pf' and x->>'type'='message' and x#>>'{data,text}' like '%wa.me/%');

-- Append the new operational contract only to the installed tracking agent.
update agents a set rules=concat_ws(E'\n',a.rules,'[Regras operacionais 2026-10] Consulta por CPF/CNPJ válido também por representante; não exigir telefone do titular. Documento e e-mail mascarados. Bot primeiro: opções válidas continuam; entrada inválida de até 3 caracteres repete a pergunta; texto livre maior ou áudio passa à IA e pausa o bot. Áudio deve receber voz quando STT/TTS estiverem configurados; se falharem, informar sem inventar transcrição. Comercial tenta resolver a venda no canal; encaminhamento humano nas exceções. Informar o protocolo real do sistema. Aceite humano pausa automação; somente retomar com autorização. A espera para IA e o retorno à fila seguem a configuração de Continuidade, sem ciclo automático.'),forbidden=replace(coalesce(a.forbidden,''),'Não expor débitos de outra pessoa.','Consultar apenas o cadastro solicitado; mascarar documentos e dados sensíveis.') where exists(select 1 from settings s where s.tenant_id=a.tenant_id and s.key='template:rastreamento_veicular' and s.value->>'agent_id'=a.id::text) and coalesce(a.rules,'') not like '%[Regras operacionais 2026-10]%';
